// 1. Obter texto do CSV de Investimentos
let csvText = '';
if (typeof $input.first().json.data === 'string') {
  csvText = $input.first().json.data;
} else if (typeof $input.first().json === 'string') {
  csvText = $input.first().json;
} else {
  csvText = JSON.stringify($input.first().json);
}

// Fallback de catálogo se a requisição externa falhar
if (!csvText || !csvText.includes('perfil')) {
  csvText = `perfil,produto,minimo,rentabilidade
Conservador,Poupança,100,6.2%
Conservador,CDB Liquidez Diária,1000,12.5%
Conservador,Tesouro Selic,500,13.0%
Moderado,CDB Prefixado,1000,14.0%
Moderado,Fundo Multimercado,5000,16.0%
Moderado,Tesouro IPCA+,1000,IPCA+6.0%
Arrojado,Ações ETF,500,Variável
Arrojado,Fundo de Ações,10000,Variável
Arrojado,Criptomoedas,100,Variável`;
}

// 2. Parser do CSV
const linhasCsv = csvText.trim().split(/\r?\n/);
const catalogo = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const col = linhasCsv[i].split(',').map(s => s.trim());
  if (col.length >= 4) {
    catalogo.push({
      perfil: col[0],
      produto: col[1],
      minimo: parseFloat(col[2]) || 0,
      rentabilidade: col[3]
    });
  }
}

// 3. Obter os dados enviados pelo RPA ao Webhook
const webhookData = $('Webhook - Receber Clientes (RPA)').first().json;
const webhookBody = webhookData.body || webhookData;
const clientes = Array.isArray(webhookBody) ? webhookBody : (webhookBody.clientes || [webhookBody]);

// Parâmetro opcional: se o cliente enviar 'usar_ia': true no JSON, roteia para o Agente de IA
const usarIaGlobal = webhookBody.usar_ia === true || webhookData.query?.ia === 'true';

function converterSaldo(valor) {
  if (typeof valor === 'number') return valor;
  const limpo = String(valor || '0').replace(/[^0-9,-]/g, '').replace(',', '.');
  return parseFloat(limpo) || 0;
}

const itensProcessados = [];

// 4. Cruzamento de cada cliente com a base de investimentos
for (const cliente of clientes) {
  if (!cliente || !cliente.nome) continue;

  const perfil = (cliente.perfil || 'Conservador').trim();
  const saldoNum = converterSaldo(cliente.saldo);

  const produtosPerfil = catalogo.filter(p => p.perfil.toLowerCase() === perfil.toLowerCase());
  const produtosAcessiveis = produtosPerfil.filter(p => saldoNum >= p.minimo);

  const produtoPrincipal = produtosAcessiveis.length > 0
    ? produtosAcessiveis[produtosAcessiveis.length - 1]
    : (produtosPerfil[0] || { produto: 'Tesouro Selic', rentabilidade: '13.0%', minimo: 500 });

  const outrosProdutos = produtosAcessiveis
    .filter(p => p.produto !== produtoPrincipal.produto)
    .map(p => p.produto);

  // Template Estático Padrão (Garante funcionamento MVP sem depender de API externa)
  let templateEstatico = '';
  if (perfil.toLowerCase() === 'conservador') {
    templateEstatico = `Olá, ${cliente.nome}! 🛡️ Com perfil Conservador e saldo de ${cliente.saldo}, sua prioridade é segurança e liquidez. Recomendamos ${produtoPrincipal.produto} com rentabilidade de ${produtoPrincipal.rentabilidade} (mínimo R$ ${produtoPrincipal.minimo}). ${outrosProdutos.length > 0 ? 'Outras opções seguras: ' + outrosProdutos.join(', ') + '.' : ''}`;
  } else if (perfil.toLowerCase() === 'moderado') {
    templateEstatico = `Olá, ${cliente.nome}! ⚖️ Com perfil Moderado e saldo de ${cliente.saldo}, recomendamos ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade}) para equilibrar segurança de renda fixa com valorização. ${outrosProdutos.length > 0 ? 'Opções complementares: ' + outrosProdutos.join(', ') + '.' : ''}`;
  } else if (perfil.toLowerCase() === 'arrojado') {
    templateEstatico = `Olá, ${cliente.nome}! 🚀 Como investidor Arrojado com saldo de ${cliente.saldo}, você tem foco em alto potencial de retorno. Sugerimos ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade}, mínimo R$ ${produtoPrincipal.minimo}). ${outrosProdutos.length > 0 ? 'Alternativas para diversificar: ' + outrosProdutos.join(', ') + '.' : ''}`;
  } else {
    templateEstatico = `Olá, ${cliente.nome}! Recomendamos ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade}).`;
  }

  // Prompt estruturado caso o fluxo de IA seja acionado
  const promptIa = `Você é um Consultor Financeiro de Investimentos sênior da DIO Invest.\nCrie uma mensagem acolhedora, personalizada e persuasiva para o cliente:\n- Nome: ${cliente.nome}\n- Perfil: ${perfil}\n- Saldo Disponível: ${cliente.saldo}\n- Recomendação Principal: ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade}, aporte mínimo R$ ${produtoPrincipal.minimo})\n- Opções complementares: ${outrosProdutos.join(', ') || 'Nenhuma'}\n\nRegras:\n1. Destaque por que a opção se alinha ao perfil ${perfil}.\n2. Tom amigável, humanizado e focado em educação financeira.\n3. Máximo de 2 parágrafos curtos com emojis adequados.`;

  itensProcessados.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldo_numerico: saldoNum,
      perfil: perfil,
      produto_recomendado: produtoPrincipal.produto,
      rentabilidade: produtoPrincipal.rentabilidade,
      minimo_exigido: produtoPrincipal.minimo,
      outras_opcoes: outrosProdutos,
      mensagem_estatica: templateEstatico,
      prompt_ia: promptIa,
      usar_ia: usarIaGlobal,
      tipo_mensagem: usarIaGlobal ? 'Aguardando IA' : 'Template Estático (MVP)',
      data_processamento: new Date().toISOString()
    }
  });
}

return itensProcessados;

// Mescla o resultado gerado pela IA com as informações originais
const resultados = [];
for (let i = 0; i < $items().length; i++) {
  const original = $('Cruzar Dados (Clientes x Investimentos)').all()[i].json;
  const textoIa = $items()[i].json.text || $items()[i].json.response || $items()[i].json;

  resultados.push({
    json: {
      nome: original.nome,
      email: original.email,
      saldo: original.saldo,
      perfil: original.perfil,
      produto_recomendado: original.produto_recomendado,
      rentabilidade: original.rentabilidade,
      mensagem_final: typeof textoIa === 'string' ? textoIa : JSON.stringify(textoIa),
      tipo_mensagem: "IA Generativa (Google Gemini)",
      data_processamento: original.data_processamento
    }
  });
}
return resultados;

// Define a mensagem final como o template estático do MVP
return $items().map(item => ({
  json: {
    nome: item.json.nome,
    email: item.json.email,
    saldo: item.json.saldo,
    perfil: item.json.perfil,
    produto_recomendado: item.json.produto_recomendado,
    rentabilidade: item.json.rentabilidade,
    outras_opcoes: item.json.outras_opcoes,
    mensagem_final: item.json.mensagem_estatica,
    tipo_mensagem: "Template Estático (MVP)",
    data_processamento: item.json.data_processamento
  }
}));

